def flatten(obj):
    """Deep-flatten nested lists/tuples, yield dict values in place, treat strings as atoms."""
    if isinstance(obj, (list, tuple)):
        for item in obj:
            yield from flatten(item)
    elif isinstance(obj, dict):
        for v in obj.values():
            yield from flatten(v)
    else:
        yield obj
